import {checkRequirement,subjectSelectionValid,csvCell} from './engine.js';
import {PLANNER_VERSION,normalize,buildHistoricalIndex,makePreviewProjects,generatePlan,planMissing,importPrograms,validateReview,programFingerprint,retrospectiveCheck} from './planner-engine.js';
import {initialState,loadWorkspace,saveWorkspace,audit} from './workspace-store.js';
import {scoreToHistoricalRank,selectionFingerprint,compactPlanResult} from './planning-helpers.js';
import {tasks} from './majors.js';

const e=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const n=s=>Number(s||0).toLocaleString('zh-CN');
const fields=['年份','生源省份','科类','批次','计划性质','学校','专业','院校代号','专业代号','校区','学校所在省','学校所在市','办学性质','招生人数','学制','年学费','选科要求','语种要求','体检及单科要求','计划来源','章程来源','公布日期','计划状态'];
const bands={margin:'历史余量较大',ahead:'位次在历史区间前',within:'位次落在历史波动区',reach:'位次弱于历史区间',unknown:'历史不足'};
const button=(label,action,extra='')=>`<button class="btn ${extra}" data-ws="${action}">${label}</button>`;
function download(name,content,type='application/json;charset=utf-8'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function createWorkspace({root,getProfile,getRequirements,getRecommendations,toast}){
 let state=initialState(),data,histIndex,ready,active='planner',storageWarning='',programPage=0,programQuery='',historyPage=0,historyQuery={year:'2026',category:'物理',school:'',major:''},staged=[],importError='',lastResult=null;
 const persist=()=>saveWorkspace(state).catch(()=>{storageWarning='本机保存失败，请立即导出备份。关闭页面后未保存内容可能丢失。';toast(storageWarning);});
 const source=id=>data.sources.find(s=>s.id===id);
 const current=()=>state.versions.find(v=>v.id===state.selectedVersion)||null;
 const date=s=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
 async function init(){if(ready)return ready;ready=(async()=>{try{state=await loadWorkspace();}catch{storageWarning='当前浏览器不能持久保存工作台；可以使用并导出，刷新会丢失未备份记录。';}
  const r=await fetch('./planning-data.json');if(!r.ok)throw Error('历史数据加载失败');data=await r.json();data.cutoffs=(await Promise.all(data.cutoffFiles.map(async file=>{const x=await fetch('./'+file);if(!x.ok)throw Error('历史数据分卷加载失败');return x.json();}))).flat();histIndex=buildHistoricalIndex(data);state.settings={...initialState().settings,...state.settings};state.programs=state.programs||[];state.qualified=state.qualified||{};
 })();return ready;}
 function heading(k,title,body){return `<div class="intro"><div class="eyebrow">${k}</div><h1>${title}</h1><p>${body}</p></div>`;}
 function revision(){return `${data.version}:${state.revision}`;}
 function warning(){return storageWarning?`<div class="notice warn">${e(storageWarning)}</div>`:'';}
 function snapshotIsStale(v){return v&&(v.dataRevision!==revision()||v.result.metadata.engineVersion!==PLANNER_VERSION||v.result.metadata.conditionsFingerprint!==selectionFingerprint(getProfile(),state.settings));}
 function versionNote(v){return snapshotIsStale(v)?'<div class="notice error" role="status"><strong>这是旧条件或旧规则下的方案快照。</strong>数据、选科、学习底线或筛选条件已变化，请重新生成；收藏与历史快照仍保留，不能当成当前条件的结果。</div>':'';}
 function refreshSnapshotNote(){const node=document.getElementById('wsSnapshotNote');if(node)node.innerHTML=versionNote(current());}
 function ensureRankBasis(){const s=state.settings;if(s.rankBasis&&s.rankBasis.category!==getProfile().first){s.rank='';s.rankBasis=null;persist();}}
 function rankHelper(){const s=state.settings,p=getProfile(),basis=s.rankBasis;
  return `<details class="panel" ${!s.rank||basis?'open':''}><summary>只有分数？换算历史参考位次</summary><p class="hint">输入模拟分数，查所选历史年份的一分一段表，取同分段末位用于预选。仅限同科类历史对照，不是2027位次预测；不会覆盖专业探索里手动填写的位次。</p><div class="grid2"><label class="ws-field">参考年份<select data-ws-field="scoreYear">${[2026,2025,2024,2023].map(y=>`<option value="${y}" ${+s.scoreYear===y?'selected':''}>${y}年</option>`).join('')}</select></label>${settingsInput('模拟考试分数','scoreInput','number','请输入分数','min="0" max="750" step="1"')}</div><p class="hint">当前科类：${e(p.first||'请先设置首选科目')}。只使用已通过一致性校验的精确分数档，缺档不补齐。</p>${button('换算并用于预选','convertScore','primary')}<p id="wsScoreError" class="error-message" role="alert"></p>${basis?`<p class="notice" id="wsRankBasis">当前采用 ${basis.year} 年${e(basis.category)}类 ${basis.score} 分，同分段 ${n(basis.low)}—${n(basis.high)} 位；参考位次 ${n(basis.rank)}。<a href="${e(source('scores-'+basis.year)?.url)}" target="_blank" rel="noopener noreferrer">查看历史一分一段原表</a></p>`:''}</details>`;
 }
 function editable(){let v=current();if(!v)return null;if(!v.editing){v=structuredClone(v);v.id='v-'+crypto.randomUUID();v.created=new Date().toISOString();v.name=v.name.replace(/ · 编辑稿$/,'')+' · 编辑稿';v.editing=true;state.versions.unshift(v);state.versions=state.versions.slice(0,12);state.selectedVersion=v.id;}return v;}
 function settingsInput(label,key,type='text',placeholder='',extra=''){const value=state.settings[key]??'';return `<label class="ws-field">${label}<input class="input" data-ws-field="${key}" type="${type}" value="${e(value)}" placeholder="${e(placeholder)}" ${extra}></label>`;}
 function plannerPage(){ensureRankBasis();const report=retrospectiveCheck(histIndex,data.cutoffs,2026);const p=getProfile(),s=state.settings,v=current(),approved=state.programs.filter(x=>x.reviewed&&x.year===Number(s.year)).length;
 return `${heading('96志愿工作台 / 河北普通本科批','从个人条件，生成可以逐项解释的方案','先生成预选草案，再补齐年度计划与资格核验。系统只在你允许的范围内选择，不会为凑满96项自动放宽条件。')}${warning()}<details class="panel"><summary>先了解历史比较的可靠程度</summary><p>将2023—2025区间与2026实际投档比较，${n(report.examined)}项可比较项目中，仅${n(report.inside)}项与原区间重叠（${(100*report.inside/Math.max(1,report.examined)).toFixed(1)}%）。历史位次存在明显变化，不能据此给个人录取概率或保证录取。当前用于缩小候选范围，年度计划与变化仍需人工复核。</p></details>
 <div class="ws-metrics"><div><strong>${n(data.cutoffs.length)}</strong><span>2023—2026投档项目记录</span></div><div><strong>${n(data.cutoffs.filter(r=>r.rankLow).length)}</strong><span>已校验分数段位次区间</span></div><div><strong>${approved}</strong><span>所选年份本机已复核计划</span></div><div><strong>${state.versions.length}</strong><span>已保存方案快照</span></div></div>
 <div class="summarybar"><span class="tag">河北 ${p.first?e([p.first,...p.electives].join('＋')):'尚未设置选科'}</span><span class="small">${p.maxYears==='4'?'本科≤4年':'学制可灵活'}；${p.budget?'年学费预算 '+n(p.budget)+'元':'学费预算未填'}</span><button class="textbtn current-profile" data-step="0">设置或修改个人条件</button></div>
 <section class="panel"><div class="panel-header"><h3>1. 选择生成模式</h3><span class="small">普通本科批，不含艺体、提前批或专项计划</span></div><div class="ws-mode"><button class="choice ${s.mode==='preview'?'ws-active':''}" data-ws="mode:preview" aria-pressed="${s.mode==='preview'}"><strong>2027预选草案</strong><span>选科参考＋过去三年投档区间</span></button><button class="choice ${s.mode==='formal'?'ws-active':''}" data-ws="mode:formal" aria-pressed="${s.mode==='formal'}"><strong>已核验方案</strong><span>只使用当年计划与本人资格均已核对的项目</span></button></div>
 ${s.mode==='preview'?'<div class="notice">预选草案不含已确认的2027招生人数、年度填报代号或学费校区。位次如为预估，仅作探索。记录来自真实官方资料，不使用虚构项目。</div>':`<div class="notice warn">当前${s.year}年本机已复核计划${approved}项。2027正式计划尚未接入，不能由2027选科参考表代替。先在“数据工作台”补充当年正式计划，再逐项确认本人资格。${button('去管理数据','data','sm')}</div>`}
 <div class="grid2">${s.mode==='formal'?`<label class="ws-field">方案年份<select data-ws-field="year"><option value="2027" ${+s.year===2027?'selected':''}>2027</option><option value="2026" ${+s.year===2026?'selected':''}>2026历史模拟（严格隔离目标年投档结果）</option></select></label>`:'<div class="ws-field">方案年份<strong>2027</strong><span class="hint">历史参考固定为2024—2026，不推测未来正式计划。</span></div>'}${settingsInput('本省同类考生位次','rank','number',p.rank||'必填；预选可以填预估位次','min="1" max="1000000"')}${settingsInput('每年学费预算（元，不含生活费）','budget','number',p.budget||'留空表示不设学费上限','min="0" max="1000000"')}${settingsInput('目标志愿数（最多96）','count','number','','min="1" max="96"')}${settingsInput('每所学校最多保留几项','schoolCap','number','','min="1" max="96"')}${settingsInput('希望有几项“历史余量较大”的选择','marginCount','number','','min="0" max="96"')}</div>
 ${s.mode==='preview'?rankHelper():''}
 <div class="notice" id="wsExplorationLink"><strong>专业探索底线已联动</strong><p>${p.veto?.length?'当前底线：'+p.veto.map(k=>e(tasks[k]||k)).join('、')+'。完全同名样本中冲突的专业会自动排除；未覆盖的专业默认不进入自动方案；可按需放行，仍须逐项核对。':'尚未设置学习任务底线，可以先探索专业，再返回生成草案。'}</p><button class="textbtn" data-view="assessment">设置兴趣与学习底线</button></div>
 <label class="ws-field">可接受的专业关键词（按偏好先后，多个用逗号分隔）<input class="input" data-ws-field="majors" value="${e(s.majors)}" placeholder="例如：计算机，软件，电子信息；留空不限定"><span class="hint">关键词按名称包含匹配；学习任务仅对42个完全同名样本自动检查，相近专业、方向和专业类仍须自行核对。${button('带入专业探索前三项','useRecommendations','sm')}</span></label>
 ${settingsInput('明确排除的学校或专业关键词','avoid','text','例如：护理，中外合作')}
 <div class="ws-field"><span>接受的学校所在省份（可多选；未选表示全国）</span><div class="choices">${[...new Set(Object.values(data.schools).map(x=>x.province).filter(Boolean))].sort((a,b)=>(a==='河北省'?-1:b==='河北省'?1:a.localeCompare(b,'zh'))).map(x=>`<button class="choice" data-ws="province:${x}" aria-pressed="${s.provinces.includes(x)}">${x}</button>`).join('')}</div><span class="hint">筛选依据为教育部学校所在地，实际就读校区仍须核查；选了地区后，所在地未知的项目不会混入。</span></div>
 <label class="ws-field">历史风险探索范围<select data-ws-field="strategy"><option value="cautious" ${s.strategy==='cautious'?'selected':''}>保守探索：位次不超过历史中位区间的1.05倍</option><option value="balanced" ${s.strategy==='balanced'?'selected':''}>均衡探索：上限1.20倍</option><option value="explore" ${s.strategy==='explore'?'selected':''}>拓展探索：上限1.35倍</option></select><span class="hint">这是可解释的筛选阈值，不是经过校准的录取概率。前三年无法精确对应的项目不进入自动生成。</span></label>
 <div class="choices"><label class="checklabel"><input type="checkbox" data-ws-check="allowPrivate" ${s.allowPrivate?'checked':''}>接受民办院校</label><label class="checklabel"><input type="checkbox" data-ws-check="allowCooperation" ${s.allowCooperation?'checked':''}>接受名称中含合作或高收费标识的项目</label>${s.mode==='preview'&&p.veto?.length?`<label class="checklabel"><input type="checkbox" data-ws-check="allowUnknownTasks" ${s.allowUnknownTasks?'checked':''}>预选允许学习任务尚待核实的专业</label>`:''}${s.mode==='preview'?`<label class="checklabel"><input type="checkbox" data-ws-check="allowUnknownCost" ${s.allowUnknownCost?'checked':''}>预选允许学费或学制待核项目</label>`:''}</div><p class="hint">没有合作标识不等于已排除所有合作项目；正式计划与章程仍须复核。</p>
 <div class="actions"><button class="btn" data-view="assessment">继续探索专业</button><button class="btn primary" data-ws="generate">${s.mode==='preview'?'生成预选草案':'生成已核验方案'} →</button></div><div id="wsError" class="error-message" role="alert"></div></section>
 ${s.mode==='formal'?qualificationPanel():''}${v?resultPanel(v):'<section class="empty"><h3>完成条件后，生成第一份方案</h3><p>会显示每项的推荐依据、历史范围、资料出处与待核事项。数据不足时解释缺口，不拼凑数量。</p></section>'}`;
 }
 function qualificationPanel(){const list=state.programs.filter(r=>r.reviewed&&r.year===Number(state.settings.year)&&r.category===getProfile().first);return `<details class="panel"><summary>2. 本人资格逐项确认（${list.length}个已复核项目）</summary><p class="hint">项目数据复核不代表你本人符合条件。对照链接中的体检、语种、单科和其他要求后逐项确认。资料修改后确认自动失效。</p>${list.length?list.map(r=>`<div class="ws-review-row"><div><strong>${e(r.school)} · ${e(r.major)}</strong><p class="hint">${e(r.language)}；${e(r.healthRule)}；${e(r.campus)}。<a href="${e(r.charter)}" target="_blank" rel="noopener noreferrer">查看章程</a></p></div><label class="checklabel"><input type="checkbox" data-ws-qualify="${e(r.id)}" ${state.qualified[r.id]===programFingerprint(r)?'checked':''}>我已对照并确认本人符合</label></div>`).join(''):'<p>没有可确认的项目。请先补齐并复核年度正式计划。</p>'}</details>`;}
 function resultPanel(v){const r=v.result,stale=snapshotIsStale(v);return `<section id="wsResults"><div id="wsSnapshotNote">${versionNote(v)}</div><div class="toolbar"><div><h2 style="margin:0">${e(v.name)}</h2><span class="small">${date(v.created)} · ${v.result.metadata?.mode==='formal'?'已核验参考方案':'预选草案'} · 规则${e(v.result.metadata.engineVersion)}</span></div><div class="choices">${button('保存为新快照','saveSnapshot','sm')}${button('导出CSV','exportPlan','sm')}${button('打印报告','printPlan','sm')}</div></div>
 <div class="ws-metrics"><div><strong>${r.rows.length}</strong><span>已选项目 / 目标${r.metadata?.settings?.count||96}</span></div><div><strong>${r.stats.schools||0}</strong><span>涉及学校</span></div><div><strong>${r.stats.bandCounts?.margin||0}</strong><span>历史余量较大项目</span></div><div><strong>${r.rows.filter(x=>x.locked).length}</strong><span>锁定项目</span></div></div>
 ${(r.rows.length<Number(r.metadata.settings.count)?[`当前仅${r.rows.length}项，距目标还差${Number(r.metadata.settings.count)-r.rows.length}项。`]:[]).concat(r.gaps).map(x=>`<div class="notice warn">${e(x)}</div>`).join('')}<p class="method">排序是便于比较的初稿，不是考生最终意愿。调整顺序后仍须逐条确认；历史投档分也不等于最终录取分。${stale?'当前结果为旧条件或旧规则快照。':''}</p>
 <div class="tablewrap"><table class="ws-plan-table"><thead><tr><th>顺序</th><th>学校＋专业</th><th>历史位置</th><th>资格与费用</th><th>操作</th></tr></thead><tbody>${r.rows.map((x,i)=>`<tr><td>${i+1}${x.locked?'<span class="small">已锁定</span>':''}</td><td><strong>${e(x.school)}</strong><span class="small">${e(x.major)}</span><span class="small">${e(x.schoolProvince||'学校所在地待核')} ${e(x.city)}</span><span class="small">${r.metadata.mode==='formal'?`当年代号 ${e(x.schoolCode)} / ${e(x.majorCode)}`:'当年填报代号待核，勿用选科表代码代替'}</span></td><td><span class="tag ${x.risk.band==='reach'?'warn':''}">${e(x.risk.label)}</span>${x.history.map(h=>`<span class="small">${h.year}：${h.score}分 · ${n(h.rankLow)}—${n(h.rankHigh)}位</span>`).join('')}</td><td>${x.tuition===null||x.tuition===undefined?'学费待核':n(x.tuition)+'元/年'}<span class="small">${e(x.campus||'实际校区待核')}</span><span class="small">${e(x.pending.join('；')||'项目及本人资格已人工对照')}</span></td><td><div class="table-actions">${button('详情','project:'+i,'sm')}${button(x.locked?'解锁':'锁定','lock:'+i,'sm')}${button('↑','move:'+i+':-1','sm')}${button('↓','move:'+i+':1','sm')}${button('移除','remove:'+i,'sm')}</div></td></tr>`).join('')||'<tr><td colspan="5">没有符合当前规则的项目。请检查下方原因。</td></tr>'}</tbody></table></div>
 <details class="panel"><summary>为什么其他项目没有进入？</summary><ul class="source-list">${Object.entries(r.stats.reasonCounts||{}).sort((a,b)=>b[1]-a[1]).map(([k,count])=>`<li>${e(k)}：${n(count)}项</li>`).join('')||'<li>当前年份没有可用的年度正式计划。</li>'}</ul><p class="hint">同一项目可能有多项原因，计数不能简单相加。另有同校上限、同名去重与目标数量限制。</p></details>
 <label class="ws-field">考生与家庭的取舍记录<textarea data-ws-notes placeholder="记录最想去的项目、家庭不同意见，以及最终取舍理由。">${e(v.notes||'')}</textarea></label>
 <details class="panel"><summary>方案版本与恢复</summary><p class="hint">修改和数据更新保留版本依据。恢复旧版本只恢复草案，不使过期数据重新有效。</p><div class="ws-version-list">${state.versions.map(x=>`<div><strong>${e(x.name)}</strong><span class="small">${date(x.created)} · ${x.result.rows.length}项 · ${!snapshotIsStale(x)?'与当前条件一致':'旧条件或旧规则'}</span>${button('查看快照','version:'+x.id,'sm')}</div>`).join('')}</div></details></section>`;}
 function dataPage(){const queue=state.programs.filter(r=>(r.school+' '+r.major+' '+r.year).includes(programQuery));programPage=Math.min(programPage,Math.max(0,Math.ceil(queue.length/30)-1));const reviewed=state.programs.filter(r=>r.reviewed).length,report=retrospectiveCheck(histIndex,data.cutoffs,2026);return `${heading('数据工作台 / 来源与核验','让每个判断都有依据','当前为本机数据工作台。计划、审核记录与方案保存在本浏览器，不会自动同步到其他设备；可导出备份迁移。')}${warning()}<div class="ws-metrics"><div><strong>${n(data.cutoffs.length)}</strong><span>真实历史投档项目</span></div><div><strong>${n(Object.keys(data.schools).length)}</strong><span>教育部高校所在地记录</span></div><div><strong>${state.programs.length}</strong><span>本机年度计划</span></div><div><strong>${reviewed}</strong><span>本机人工复核计划</span></div></div>
 <div class="panel"><h3>数据就绪情况</h3><ul class="source-list"><li>2023—2026本科普通批物理、历史：已接入原表；投档最低分、同分排序项和备注保留。</li><li>一分一段：仅采用通过累计人数校验的分数档；位次显示为同分段区间，不伪造末位考生精确名次。</li><li>2027选科：沿用原91,789条参考记录，不视为2027年度计划。</li><li>2026正式计划：仅取得一家高校的18条普通本科分省样本，缺代码、校区与章程核验，不自动标为已审核。</li><li>2027正式计划：未接入；不能发布已具备实际填报效力的2027方案。</li><li>回测：${e(report.label)}。以2023—2025形成区间，检查2026实际投档同分段是否与区间重叠。可比${n(report.examined)}项，重叠${n(report.inside)}项，未重叠${n(report.outside)}项，因前置资料不足等跳过${n(report.insufficient)}项；这不是个人录取概率；跨年选科政策、计划人数及项目变化仍会影响可比性。</li></ul><div class="choices">${button('导入已取得的2026高校计划样本','loadSamples')}${button('备份本机工作台','backup')}<label class="btn">恢复备份<input type="file" id="wsRestore" accept=".json" hidden></label></div></div>
 <section class="panel import"><h3>导入年度正式计划，先暂存再复核</h3><p class="hint">字段包括年度填报代号、具体校区、学制、完整收费、选科、语种、体检及单科要求、计划和章程来源。缺失留空，不能填0冒充免费。导入不会自动变成“已复核”。</p><textarea id="wsPlanCSV" aria-label="年度招生计划CSV" placeholder="先下载空白模板，按来源填写后粘贴或上传CSV。"></textarea><div class="choices">${button('下载CSV模板','template')}${button('校验并暂存','stage')}<label class="btn">选择CSV文件<input type="file" id="wsImport" accept=".csv,text/csv" hidden></label></div>${importError?`<div class="error-message" role="alert">${e(importError)}</div>`:''}${staged.length?`<div class="notice">已校验${staged.length}条。${staged.filter(r=>!planMissing(r).length).length}条结构字段完整；全部仍需人工核对来源。${button('确认加入待审库','commitImport','sm')}</div>`:''}</section>
 <section class="panel"><div class="panel-header"><h3>年度计划复核队列</h3><span class="small">第${programPage+1}页，匹配${queue.length}条 / 全部${state.programs.length}条</span></div><input class="input" data-ws-program-query value="${e(programQuery)}" placeholder="搜索学校、专业或年份后按回车">${queue.length?`<div class="tablewrap"><table><thead><tr><th>项目</th><th>字段状态</th><th>复核状态</th><th>操作</th></tr></thead><tbody>${queue.slice(programPage*30,programPage*30+30).map(r=>`<tr><td><strong>${r.year} ${e(r.category)} · ${e(r.school)}</strong><span class="small">${e(r.major)} · ${e(r.campus||'校区待核')}</span></td><td>${planMissing(r).length?'缺：'+e(planMissing(r).join('、')):'结构字段完整，须核对来源'}</td><td>${r.reviewed?'本机已人工复核':'待复核'}<span class="small">${e(r.reviewBy||'')}${r.reviewAt?' · '+date(r.reviewAt):''}</span></td><td>${button('查看与复核','review:'+encodeURIComponent(r.id),'sm')}${button('移除','deleteProgram:'+encodeURIComponent(r.id),'sm')}</td></tr>`).join('')}</tbody></table></div><div class="pagination">${button('上一页','progprev','sm')}<span>${programPage+1} / ${Math.max(1,Math.ceil(queue.length/30))}</span>${button('下一页','prognext','sm')}</div>`:'<p class="muted">没有匹配的年度计划。缺数据时生成器保持空缺，不会把参考表改称正式计划。</p>'}</section>
 ${historyPanel()}<details class="panel"><summary>来源台账（${data.sources.length}份资料）</summary><div class="tablewrap"><table><thead><tr><th>资料</th><th>发布/整理日期</th><th>类型</th><th>原始文件校验</th></tr></thead><tbody>${data.sources.map(s=>`<tr><td><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)}</a><span class="small">${e(s.publisher)}</span></td><td>${e(s.published)}<span class="small">整理：${e(s.checked)}</span></td><td>${e(s.kind)}</td><td class="small ws-hash">SHA256<br>${e(s.sha256)}</td></tr>`).join('')}</tbody></table></div></details>
 <details class="panel"><summary>扫描表质量检查</summary><div class="tablewrap"><table><thead><tr><th>年份</th><th>已校验物理档</th><th>已校验历史档</th><th>未通过校验档</th></tr></thead><tbody>${data.quality.map(q=>`<tr><td>${q.year}</td><td>${q.verified['物理']||0}</td><td>${q.verified['历史']||0}</td><td>${(q.unverified['物理']||0)+(q.unverified['历史']||0)}（另有无法识别的空缺，不作补齐）</td></tr>`).join('')}</tbody></table></div><p class="hint">并非所有分数档都可用。缺失或校验不通过的档位不会进入自动方案的历史风险比较；原始分数仍可查。累计校验属于数据一致性检查，不等于对扫描识别完成了独立人工审计。</p></details>
 <details class="panel"><summary>本机操作记录</summary>${state.audit.map(a=>`<p class="small">${date(a.at)} · ${e(a.event)}：${e(a.detail)}</p>`).join('')||'<p class="muted">暂无操作。</p>'}</details>`;}
 function historyPanel(){const q=historyQuery,rows=data.cutoffs.filter(r=>r.year===+q.year&&r.category===q.category&&(!q.school||r.school.includes(q.school))&&(!q.major||r.major.includes(q.major))),pages=Math.max(1,Math.ceil(rows.length/15));historyPage=Math.min(historyPage,pages-1);return `<section class="panel"><h3>检索真实历史投档记录</h3><div class="filterrow"><label>年份<select data-ws-history="year">${[2026,2025,2024,2023].map(y=>`<option ${+q.year===y?'selected':''}>${y}</option>`).join('')}</select></label><label>科类<select data-ws-history="category"><option ${q.category==='物理'?'selected':''}>物理</option><option ${q.category==='历史'?'selected':''}>历史</option></select></label><label>学校<input class="input" data-ws-history="school" value="${e(q.school)}" placeholder="例如：河北大学"></label><label>专业<input class="input" data-ws-history="major" value="${e(q.major)}" placeholder="例如：计算机"></label></div><p class="hint">找到${n(rows.length)}项。保留原文项目名称；院校代号、专业代号仅适用于该历史年份。</p><div class="tablewrap"><table><thead><tr><th>学校与专业</th><th>年度代号</th><th>投档最低分</th><th>同分段位次区间</th><th>出处</th></tr></thead><tbody>${rows.slice(historyPage*15,historyPage*15+15).map(r=>`<tr><td>${e(r.school)}<span class="small">${e(r.major)}</span></td><td>${e(r.schoolCode)} / ${e(r.majorCode)}</td><td>${r.score??'无合格投档生源或缺值'}<span class="small">${e(r.note)}</span></td><td>${r.rankLow?n(r.rankLow)+'—'+n(r.rankHigh):'位次未通过校验或缺失'}</td><td><a href="${e(source(r.sourceId)?.url)}" target="_blank" rel="noopener noreferrer">原表第${r.sourceRow}行</a></td></tr>`).join('')||'<tr><td colspan="5">没有匹配记录。</td></tr>'}</tbody></table></div><div class="pagination">${button('上一页','histprev','sm')}<span>${historyPage+1} / ${pages}</span>${button('下一页','histnext','sm')}</div></section>`;}
 function showDialog(html){document.getElementById('dialogBody').innerHTML=html;const d=document.getElementById('detailDialog');if(!d.open)d.showModal();}
 function detail(i){const r=current()?.result.rows[i];if(!r)return;showDialog(`<h2 id="dialogTitle">${e(r.school)} · ${e(r.major)}</h2><span class="tag">${e(r.risk.label)}</span><p class="hint">只代表历史位次关系；不是录取概率或官方录取承诺。</p><div class="detailgrid"><div><h3>为什么进入方案</h3><p>${current().result.metadata.settings.majors?'命中你接受的专业关键词；':'专业范围未限定；'}选科匹配，处于当前策略的历史位次探索范围，同校数量未超过你设定的上限。</p></div><div><h3>学校与校区</h3><p>${e(r.schoolProvince)} ${e(r.city)}（学校所在地）<br>实际校区：${e(r.campus||'待核实')}<br>完整年学费：${r.tuition===null||r.tuition===undefined?'待核实':n(r.tuition)+'元'}</p></div></div><h3>过去三年的可比依据</h3><div class="tablewrap"><table><thead><tr><th>年份</th><th>专业原文</th><th>投档最低分</th><th>同分段区间</th><th>来源</th></tr></thead><tbody>${r.history.map(h=>`<tr><td>${h.year}</td><td>${e(h.major)}</td><td>${h.score}</td><td>${n(h.rankLow)}—${n(h.rankHigh)}</td><td><a href="${e(source(h.sourceId)?.url)}" target="_blank" rel="noopener noreferrer">原表第${h.sourceRow}行</a></td></tr>`).join('')}</tbody></table></div><div class="notice warn">${[...r.pending,...r.notes].map(e).join('<br>')||'项目来源及本人资格已在本机人工核对，仍须按当年官方系统核验。'}</div><p>选科要求：${e(r.requirement)}。<a href="${e(r.source)}" target="_blank" rel="noopener noreferrer">查看项目来源</a></p>${r.referenceCode?'<p class="small">选科表中的教育部专业代码不是年度河北填报代号，预选报告不输出可直接抄填的代码。</p>':''}`);}
 function review(id){const r=state.programs.find(r=>r.id===id);if(!r)return;showDialog(`<h2 id="dialogTitle">项目复核：${e(r.school)} · ${e(r.major)}</h2><p>${r.year} ${e(r.category)} ${e(r.batch)} · ${e(r.planType)}</p><p><a href="${e(r.source)}" target="_blank" rel="noopener noreferrer">核对计划原文</a>${r.charter?` · <a href="${e(r.charter)}" target="_blank" rel="noopener noreferrer">核对招生章程</a>`:''}</p><div class="notice ${planMissing(r).length?'warn':''}">${planMissing(r).length?'尚缺：'+e(planMissing(r).join('、')):'结构字段完整。请打开来源核实当年河北科类、代码、计划性质、校区、收费、选科与限制。'}</div><p class="hint">此操作是你在本机留下的人工复核记录，不是平台已完成独立专家审核。信息不足时，请按CSV模板补齐后重新导入。</p><label class="ws-field">复核人<input class="input" id="wsReviewer" value="${e(r.reviewBy||'')}" placeholder="填写复核人姓名或称呼"></label><label class="ws-field">来源核对说明（至少10字）<textarea id="wsReviewNote" placeholder="说明核对了哪些页面、年份、项目限制及差异。">${e(r.reviewNote||'')}</textarea></label><label class="checklabel"><input type="checkbox" id="wsReviewConsent">我已打开来源，逐项确认记录与当年河北正式计划及章程一致</label><div class="actions">${button(r.reviewed?'撤销复核':'保留为待核','unreview:'+encodeURIComponent(id))}${button('确认本机人工复核','approve:'+encodeURIComponent(id),'primary')}</div><div id="wsReviewError" class="error-message" role="alert"></div>`);}
 async function doGenerate(){ensureRankBasis();const p=getProfile(),s=state.settings;const year=s.mode==='preview'?2027:Number(s.year),projects=s.mode==='preview'?makePreviewProjects(getRequirements(),data,p.first):state.programs;
  // 已锁定的草案项目不会自动转入正式计划。
  const v=current(),locked=v&&v.result.metadata.mode===s.mode?v.result.rows.filter(r=>r.locked).map(r=>r.id):[];
  const r=generatePlan({projects,profile:p,settings:s,histIndex,qualified:state.qualified,locked,year,dataVersion:data.version,revision:state.revision});
  if(r.errors.length){document.getElementById('wsError').textContent=r.errors.join(' ');return;}
  const stamp=new Date().toISOString();const version={id:'v-'+crypto.randomUUID(),created:stamp,name:`${year}${s.mode==='preview'?'预选草案':'已核验参考方案'} · ${r.rows.length}项`,result:compactPlanResult(r),dataRevision:revision(),notes:state.notes};state.versions.unshift(version);state.versions=state.versions.slice(0,12);state.selectedVersion=version.id;audit(state,'生成方案',`${version.name}；目标${s.count}项；数据${revision()}`);await persist();await render('planner');document.getElementById('wsResults')?.scrollIntoView({behavior:'smooth',block:'start'});
 }
 function exportPlan(){const v=current();if(!v)return;const r=v.result;const rows=[['方案性质','顺序','年份','科类','学校','专业','当年院校代号','当年专业代号','历史位置','实际校区','年学费','待核事项','数据版本','生成时间','快照状态','参考位次','位次来源'],...r.rows.map((x,i)=>[r.metadata.mode==='preview'?'预选草案，非正式填报表':'已核验参考方案，须本人确认',i+1,r.metadata.year,x.category,x.school,x.major,r.metadata.mode==='formal'?x.schoolCode:'待核',r.metadata.mode==='formal'?x.majorCode:'待核',x.risk.label,x.campus||'待核',x.tuition??'待核',x.pending.join('；'),v.dataRevision,v.created,snapshotIsStale(v)?'旧条件或旧规则，须重新生成':'生成时条件快照',r.metadata.profile.rank,r.metadata.rankBasis?`${r.metadata.rankBasis.year}年${r.metadata.rankBasis.category}类${r.metadata.rankBasis.score}分历史换算（非2027预测）`:'手动参考位次'])];download(`${r.metadata.year}河北-${r.metadata.mode==='preview'?'预选草案':'已核验参考方案'}.csv`,'\uFEFF'+rows.map(x=>x.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
 function printPlan(){const v=current();if(!v)return;const r=v.result;document.getElementById('printReport').innerHTML=`<h1>${e(v.name)}</h1><p>${r.metadata.mode==='preview'?'预选草案，不是正式填报表。':'已核验参考方案，仍须考生在官方系统确认。'}</p><p>科目：${e([r.metadata.profile.first,...r.metadata.profile.electives].join('＋'))}；位次${n(r.metadata.profile.rank)}；数据${e(v.dataRevision)}；生成于${date(v.created)}。</p>${snapshotIsStale(v)?'<p>注意：条件、数据或规则已变化，本报告为旧快照，须重新生成。</p>':''}${r.metadata.rankBasis?`<p>位次来源：${r.metadata.rankBasis.year}年${e(r.metadata.rankBasis.category)}类${r.metadata.rankBasis.score}分历史换算，非2027预测。</p>`:'<p>位次来源：手动参考位次。</p>'}${r.gaps.map(x=>`<p>${e(x)}</p>`).join('')}<table><thead><tr><th>序号</th><th>学校＋专业</th><th>前三年历史依据</th><th>待核事项</th></tr></thead><tbody>${r.rows.map((x,i)=>`<tr><td>${i+1}</td><td>${e(x.school)}<br>${e(x.major)}<br>${r.metadata.mode==='formal'?e(x.schoolCode)+' / '+e(x.majorCode):'年度填报代号待核'}</td><td>${e(x.risk.label)}<br>${x.history.map(h=>`${h.year}：${h.score}分，${n(h.rankLow)}—${n(h.rankHigh)}位`).join('<br>')}</td><td>${e(x.pending.join('；')||'本机已人工对照')}<br>${e(x.campus||'校区待核')}，${x.tuition??'学费待核'}</td></tr>`).join('')}</tbody></table><h2>取舍记录</h2><p>${e(v.notes||'尚未填写')}</p><h2>来源依据</h2>${[...new Set(r.rows.flatMap(x=>x.history.map(h=>h.sourceId)))].map(id=>`<p class="small">${e(source(id)?.title)}：${e(source(id)?.url)}</p>`).join('')}<p class="small">历史位次为同分段区间；不是精确末位考生名次。最终须按真实意愿排序，核对当年计划、代码、体检、语种、单科、校区、收费和其他条件；不能由本网站代替官方系统提交。</p>`;window.print();}
 async function render(next){active=next;root.dataset.workspace=next;root.innerHTML='<div class="loading" role="status">正在读取真实历史数据与本机方案…</div>';try{await init();if(root.dataset.workspace!==active)return;root.innerHTML=active==='data'?dataPage():plannerPage();}catch(err){root.innerHTML=`<div class="empty"><h2>工作台暂未加载</h2><p>${e(err.message)}。专业探索功能仍可从顶部进入。</p>${button('重试','retry')}</div>`;ready=null;}}
 document.addEventListener('click',async event=>{const b=event.target.closest('button[data-ws]');if(!b||!data)return;const action=b.dataset.ws;const [cmd,...rest]=action.split(':');
  if(cmd==='data'){document.querySelector('header [data-view="data"]').click();return;}
  if(cmd==='retry'){render(active);return;}
  if(cmd==='mode'){if(rest[0]==='formal'&&state.settings.rankBasis){state.settings.rank='';state.settings.rankBasis=null;}state.settings.mode=rest[0];state.settings.year=2027;persist();render(active);return;}
  if(cmd==='province'){const name=rest.join(':');state.settings.provinces=state.settings.provinces.includes(name)?state.settings.provinces.filter(x=>x!==name):[...state.settings.provinces,name];persist();render(active);return;}
  if(cmd==='generate'){await doGenerate();return;}
  if(cmd==='convertScore'){try{const basis=scoreToHistoricalRank(data,state.settings.scoreYear,getProfile().first,state.settings.scoreInput);state.settings.rank=String(basis.rank);state.settings.rankBasis=basis;audit(state,'分数换算历史参考位次',`${basis.year} ${basis.category} ${basis.score}分 → ${basis.rank}位，非2027预测`);await persist();await render(active);}catch(err){document.getElementById('wsScoreError').textContent=err.message;}return;}
  if(cmd==='useRecommendations'){const ranked=getRecommendations().slice(0,3);if(!ranked.length)return toast('请先回答专业探索问题，或直接填写你接受的专业关键词。');state.settings.majors=ranked.map(x=>x.name).join('，');persist();render(active);return;}
  if(cmd==='project'){detail(+rest[0]);return;}
  if(['lock','move','remove'].includes(cmd)){const v=editable();if(!v)return;const i=+rest[0];if(cmd==='lock')v.result.rows[i].locked=!v.result.rows[i].locked;if(cmd==='move'){const j=i+Number(rest[1]);if(j>=0&&j<v.result.rows.length)[v.result.rows[i],v.result.rows[j]]=[v.result.rows[j],v.result.rows[i]];}if(cmd==='remove'){if(v.result.rows[i].locked)return toast('请先解除锁定。');v.result.rows.splice(i,1);}v.result.stats.schools=new Set(v.result.rows.map(r=>r.school)).size;v.result.stats.selected=v.result.rows.length;v.result.stats.bandCounts={};v.result.rows.forEach(r=>v.result.stats.bandCounts[r.risk.band]=(v.result.stats.bandCounts[r.risk.band]||0)+1);audit(state,'调整草案',cmd+'；方案'+v.id);await persist();render(active);return;}
  if(cmd==='saveSnapshot'){const v=current();if(!v)return;const clone=structuredClone(v);clone.editing=false;v.editing=false;clone.id='v-'+crypto.randomUUID();clone.created=new Date().toISOString();clone.name=v.name+' · 调整快照';state.versions.unshift(clone);state.versions=state.versions.slice(0,12);state.selectedVersion=clone.id;audit(state,'保存快照',clone.name);persist();render(active);return;}
  if(cmd==='version'){state.selectedVersion=rest.join(':');persist();render(active);return;}
  if(cmd==='exportPlan'){exportPlan();return;}if(cmd==='printPlan'){printPlan();return;}
  if(cmd==='progprev'||cmd==='prognext'){programPage=Math.max(0,programPage+(cmd==='progprev'?-1:1));render('data');return;}
  if(cmd==='histprev'||cmd==='histnext'){historyPage=Math.max(0,historyPage+(cmd==='histprev'?-1:1));render('data');return;}
  if(cmd==='template'){download('河北年度招生计划-导入模板.csv','\uFEFF'+fields.join(',')+'\r\n','text/csv;charset=utf-8');return;}
  if(cmd==='stage'){try{staged=importPrograms(document.getElementById('wsPlanCSV').value);importError='';}catch(err){staged=[];importError=err.message;}render('data');return;}
  if(cmd==='commitImport'){const map=new Map(state.programs.map(r=>[r.id,r]));staged.forEach(r=>{map.set(r.id,r);delete state.qualified[r.id];});state.programs=[...map.values()];state.revision++;state.revisionDate=new Date().toISOString();audit(state,'导入待审计划',`${staged.length}条；覆盖同ID项目将撤销复核与本人资格确认`);staged=[];await persist();render('data');return;}
  if(cmd==='loadSamples'){const exists=new Set(state.programs.map(r=>r.id));for(const sample of data.planSamples)if(!exists.has(sample.id))state.programs.push({...sample,planStatus:'正式',language:'',healthRule:'',reviewRevision:0});state.revision++;audit(state,'加载真实样本','2026金华职业技术大学18条，全部保持待审');await persist();render('data');return;}
  if(cmd==='review'){review(decodeURIComponent(rest.join(':')));return;}
  if(cmd==='approve'){const id=decodeURIComponent(rest.join(':')),r=state.programs.find(x=>x.id===id),reviewer=document.getElementById('wsReviewer').value,note=document.getElementById('wsReviewNote').value,consent=document.getElementById('wsReviewConsent').checked;const errs=validateReview(r,reviewer,note);if(!consent)errs.push('须确认已打开来源逐项核对');if(errs.length){document.getElementById('wsReviewError').textContent='不能复核通过：'+errs.join('、');return;}r.reviewed=true;r.reviewBy=reviewer.trim();r.reviewNote=note.trim();r.reviewAt=new Date().toISOString();r.reviewRevision=(r.reviewRevision||0)+1;delete state.qualified[id];state.revision++;audit(state,'本机人工复核',`${r.year} ${r.school} ${r.major}；${r.reviewBy}`);await persist();document.getElementById('detailDialog').close();render(active);return;}
  if(cmd==='unreview'||cmd==='deleteProgram'){const id=decodeURIComponent(rest.join(':')),r=state.programs.find(x=>x.id===id);if(cmd==='unreview'&&r){r.reviewed=false;r.reviewRevision=(r.reviewRevision||0)+1;}if(cmd==='deleteProgram')state.programs=state.programs.filter(x=>x.id!==id);delete state.qualified[id];state.revision++;audit(state,'计划状态变更',cmd+' '+id);await persist();document.getElementById('detailDialog').close();render(active);return;}
  if(cmd==='backup'){download('河北志愿罗盘-本机工作台备份.json',JSON.stringify({...state,backupKind:'hebei-workspace-v2',exported:new Date().toISOString()},null,2));return;}
 });
 document.addEventListener('change',async ev=>{const t=ev.target;if(t.hasAttribute('data-ws-program-query')){programQuery=t.value;programPage=0;render('data');}if(t.dataset.wsField){state.settings[t.dataset.wsField]=t.value;if(t.dataset.wsField==='rank'){state.settings.rankBasis=null;document.getElementById('wsRankBasis')?.remove();}persist();refreshSnapshotNote();if(t.dataset.wsField==='year')render(active);}
  if(t.dataset.wsCheck){state.settings[t.dataset.wsCheck]=t.checked;persist();refreshSnapshotNote();}
  if(t.dataset.wsHistory){document.querySelectorAll('[data-ws-history]').forEach(x=>historyQuery[x.dataset.wsHistory]=x.value);historyPage=0;render('data');}
  if(t.hasAttribute('data-ws-notes')){const v=editable();if(v)v.notes=t.value.slice(0,5000);state.notes=t.value.slice(0,5000);persist();}
  if(t.dataset.wsQualify){const r=state.programs.find(r=>r.id===t.dataset.wsQualify);if(r){if(t.checked)state.qualified[r.id]=programFingerprint(r);else delete state.qualified[r.id];audit(state,'本人资格对照',`${r.school} ${r.major} ${t.checked?'确认':'撤销'}`);persist();}}
  if(t.id==='wsImport'&&t.files?.[0]){try{if(t.files[0].size>20*1024*1024)throw Error('单个CSV请控制在20MB以内。');staged=importPrograms(await t.files[0].text());importError='';}catch(err){staged=[];importError=err.message;}render('data');}
  if(t.id==='wsRestore'&&t.files?.[0]){try{if(t.files[0].size>15*1024*1024)throw Error('备份过大。');const backup=JSON.parse(await t.files[0].text());if(backup.backupKind!=='hebei-workspace-v2'||!Array.isArray(backup.programs)||!Array.isArray(backup.versions))throw Error('不是本系统的有效备份。');const safe=initialState();for(const [k,v] of Object.entries(backup.settings||{})){if(!(k in safe.settings))continue;if(k==='provinces'){if(Array.isArray(v)&&v.every(x=>typeof x==='string'))safe.settings[k]=v.slice(0,40);}else if(typeof safe.settings[k]==='boolean'){if(typeof v==='boolean')safe.settings[k]=v;}else if(typeof v==='string'||typeof v==='number')safe.settings[k]=v;}if(!['preview','formal'].includes(safe.settings.mode))safe.settings.mode='preview';safe.programs=backup.programs.filter(r=>r&&typeof r.school==='string'&&typeof r.major==='string'&&typeof r.id==='string'&&/^https?:\/\//.test(r.source||'')).map(r=>({...r,charter:/^https?:\/\//.test(r.charter||'')?r.charter:'',reviewed:false,reviewRevision:(Number(r.reviewRevision)||0)+1}));safe.versions=[];safe.qualified={};safe.revision=state.revision+1;safe.notes=String(backup.notes||'').slice(0,5000);state=safe;audit(state,'恢复备份','计划全部撤回复核；本人确认及方案须重建，避免把外部文件的已审状态直接当作可信依据');await persist();toast('已恢复条件与待审计划；请重新复核及生成方案。');render('data');}catch(err){toast('恢复失败：'+err.message);}}
 });
 return {render,init};
}
